insert into public.categories (id,main,name,keywords,extra,sort_order) values
('bicycle','교통·도로','공유자전거 방치·통행 방해',ARRAY['타슈','공유자전거','공공자전거','대여자전거','자전거 방치','넘어진 자전거','쓰러진 자전거','엎어진 자전거','자전거가 넘어','자전거가 쓰러','자전거가 엎어','타슈가 엎어','타슈가 넘어','타슈가 쓰러','자전거 통행 방해','타슈 방치','타슈 반납','타슈 대여소','자전거 무단방치','자전거가 길을 막'],'자전거 위치와 통행을 막는 상태를 기록해 주세요. 타슈 등 운영 서비스의 공식 문의 창구에서 회수·정리 요청 방법을 확인할 수 있습니다. 위험한 차도로 들어가 직접 옮기지 마세요.',13),
('scooter','교통·도로','전동킥보드 방치·통행 방해',ARRAY['킥보드','전동킥보드','공유킥보드','전동스쿠터','킥보드 방치','킥보드가 넘어','킥보드가 쓰러','킥보드가 엎어','쓰러진 킥보드','넘어진 킥보드','킥보드 통행 방해','킥보드 무단주차','킥보드 반납','킥보드가 길을 막','전동 킥보드'],'기기 위치와 운영사 표시, 보행을 막는 상태를 기록해 주세요. 운영사의 공식 문의 창구에서 수거 요청 방법을 확인해 주세요.',14),
('obstruction','교통·도로','보행로 적치물·장애물',ARRAY['적치물','노상적치','보행로 적치','인도 적치','길을 막은 물건','통로에 쌓인','인도에 쌓인','보도에 쌓인','보행로 장애물','통행 장애물','입간판','화분이 길을','박스가 길을','공사 자재','쌓아둔 자재','보행로를 막','인도를 막','통로를 막'],'어떤 물건이 어느 통로를 얼마나 막고 있는지 기록해 주세요. 물건 소유자의 개인정보는 올리지 마세요.',15),
('accessibility','교통·도로','이동약자 통행 장애',ARRAY['휠체어','유모차','경사로','보도 턱','높은 턱','턱이 높','휠체어 진입','장애인 통행','시각장애인','이동약자','경사로가 막','점자블록을 막','점자블록 위','휠체어가 못','유모차가 못','보행약자'],'점자블록, 경사로, 보도 턱 등 어떤 시설에서 통행이 어려운지 기록해 주세요. 이용자의 얼굴이나 장애 관련 개인정보는 공개하지 마세요.',16)
